def git_ignored(path):
    """Apply the common .gitignore rules for a path inside a git work tree."""
    p=Path(path).resolve()
    ancestors=list(p.parents)
    repo=next((d for d in ancestors if (d/'.git').exists()),None)
    if repo is None: return False
    ignored=False
    # Rules in deeper .gitignore files override rules from their parents.
    dirs=[repo]+[d for d in reversed(ancestors[:-1]) if d!=repo and repo in d.parents]
    for base in dirs:
        ignore=base/'.gitignore'
        if not ignore.is_file(): continue
        try: lines=ignore.read_text().splitlines()
        except OSError: continue
        rel=p.relative_to(base).as_posix()
        for raw in lines:
            pat=raw.strip()
            if not pat or pat.startswith('#'): continue
            neg=pat.startswith('!')
            if neg: pat=pat[1:]
            pat=pat.replace('\\ ', ' ')
            directory=pat.endswith('/')
            pat=pat.strip('/')
            if not pat: continue
            if '/' in pat:
                hit=fnmatch.fnmatchcase(rel,pat) or (directory and rel.startswith(pat+'/'))
            else:
                parts=rel.split('/')
                hit=any(fnmatch.fnmatchcase(part,pat) for part in parts)
            if hit: ignored=not neg
    return ignored

