def toon_value(source):
    data={}
    for n,line in enumerate(source.splitlines(),1):
        t=line.strip()
        if not t or t.startswith('#'): continue
        if ':' not in t: raise ValueError(f'line {n}: expected key/value separator')
        key,raw=t.split(':',1); key=key.strip().strip('"\''); raw=raw.strip()
        if not key: raise ValueError(f'line {n}: empty key')
        if key in data: raise ValueError(f'line {n}: duplicate key {key!r}')
        if not raw: value=None
        else:
            try: value=json.loads(raw)
            except Exception:
                if raw.lower() in ('true','false'): value=raw.lower()=='true'
                elif raw.lower() in ('null','~'): value=None
                else:
                    try: value=int(raw)
                    except Exception:
                        try: value=float(raw)
                        except Exception: value=raw.strip('"\'')
        data[key]=value
    return data

def schema_diagnostic(source, violation):
    path, sep, message = violation.partition(': ')
    if not sep: path, message = '', violation
    key = path.rsplit('.',1)[-1].split('[',1)[0]
    offset = 0
    if key:
        import re
        found = list(re.finditer(r'(["\']?)'+re.escape(key)+r'\1\s*:',source))
        if found:
            offset=found[-1].start()
    line=source.count('\n',0,offset)+1
    col=offset-(source.rfind('\n',0,offset)+1)+1
    label=path or '(root)'
    return f'schema: line {line}, column {col}: {label}: {message}'

def validate_xsd(xml_text, xsd_text):
    """Validate the common element/attribute/sequence subset of XSD."""
    xs='{http://www.w3.org/2001/XMLSchema}'
    doc=ET.fromstring(xml_text); schema=ET.fromstring(xsd_text)
    root_name=doc.tag.rsplit('}',1)[-1]
    decl=next((e for e in schema.findall(xs+'element') if e.get('name')==root_name),None)
    if decl is None: return [f'element {root_name!r} is not declared in the schema']
    complex=decl.find('.//'+xs+'complexType')
    if complex is None: return []
    expected=[]
    for e in complex.findall('.//'+xs+'element'):
        if e.get('name') and e.get('minOccurs','1')!='0': expected.append(e.get('name'))
    children=[e.tag.rsplit('}',1)[-1] for e in list(doc)]
    errors=[f'missing required element {name!r}' for name in expected if name not in children]
    for attr in complex.findall('.//'+xs+'attribute'):
        if attr.get('use')=='required' and attr.get('name') not in doc.attrib:
            errors.append(f'missing required attribute {attr.get("name")!r}')
    return errors

